import React from 'react';

import PohCard from '@ui-kit/Card';
import { showModal } from '@ui-kit/Modal';

import { IHikingObstaclePhoto } from '../../@types/hikingObstacles.types';

interface IHikingObstaclePhotoItemProps {
  photo: IHikingObstaclePhoto;
  toolbar?: React.ReactNode;
}

const HikingObstaclePhotoItem: React.FC<IHikingObstaclePhotoItemProps> = ({ photo, toolbar }) => {
  return (
    <PohCard
      img={photo.url_preview}
      subtitle={photo.date.toLocaleString()}
      footer={toolbar}
      onClick={() => showModal({ canClose: true, children: <img src={photo.url} /> })}
    >
      {photo.comment}
    </PohCard>
  );
};

export default HikingObstaclePhotoItem;
